th stroke-linecap="round" d="M4 5.5h12M8 3.5h4m-6.5 2 1 11h7l1-11M8.5 8v5.5m3-5.5v5.5"/></svg>Hapus</button><?php endif; ?></div></div><?php else: ?><span class="text-xs text-slate-400">—</span><?php endif; ?></td><th scope="row" class="min-w-[8rem] break-words px-2 py-3 font-medium text-slate-900 sm:px-6 sm:py-4"><?= html_escape($flow['flow_name']) ?></th><td class="min-w-[8rem] break-words px-2 py-3 font-mono text-xs text-slate-700 sm:px-6 sm:py-4"><?= html_escape($flow['request_type']) ?></td><td class="whitespace-nowrap px-2 py-3 text-slate-700 sm:px-6 sm:py-4"><?= (int)$flow['step_count'] ?></td><td class="whitespace-nowrap px-2 py-3 sm:px-6 sm:py-4"><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-semibold <?= !empty($flow['active_flag'])?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-600' ?>"><?= !empty($flow['active_flag'])?'Aktif':'Nonaktif' ?></span></td></tr>
