<script>
(function(){var form=document.querySelector('[data-approval-live-filter]'),input=form&&form.querySelector('[name="search"]'),timer,dialog=document.getElementById('approval-flow-delete-dialog'),deleteForm=document.getElementById('approval-flow-delete-form'),name=document.getElementById('approval-flow-delete-name');if(form&&input){input.addEventListener('input',function(){clearTimeout(timer);timer=setTimeout(function(){form.requestSubmit?form.requestSubmit():form.submit();},350);});}var menus=[].slice.call(document.querySelectorAll('[data-flow-actions-menu]'));function closeMenus(){menus.forEach(function(menu){menu.hidden=true;var button=document.querySelector('[aria-controls="'+menu.id+'"][data-flow-actions-toggle]');if(button)button.setAttribute('aria-expanded','false');});}document.querySelectorAll('[data-flow-actions-toggle]').forEach(function(button){button.addEventListener('click',function(){var menu=document.getElementById(button.getAttribute('aria-controls')),opening=menu.hidden;closeMenus();if(opening){var rect=button.getBoundingClientRect();menu.style.top=(rect.bottom+4)+'px';menu.style.left=Math.max(8,rect.left)+'px';menu.hidden=false;button.setAttribute('aria-expanded','true');}});});document.addEventListener('click',function(event){if(!event.target.closest('[data-flow-actions-toggle]')&&!event.target.closest('[data-flow-actions-menu]'))closeMenus();});document.querySelectorAll('[data-flow-delete-open]').forEach(function(button){button.addEventListener('click',function(){closeMenus();name.textContent=button.getAttribute('data-flow-name')||'';deleteForm.action='/admin/hr/approvalFlow/delete/'+encodeURIComponent(button.getAttribute('data-flow-id'));dialog.showModal();});});if(dialog){dialog.querySelector('[data-flow-delete-cancel]').addEventListener('click',function(){dialog.close();});}
})();
</script>
